import{_ as i,C as t,o as r,c as s,aj as a,E as h}from"./chunks/framework.gl7gIbln.js";const d="/agentbook/images/kapitel-01-agent-arbeitsassistenz.png",l="/agentbook/diagrams/agenten-entscheidungsleiter.png",k=JSON.parse('{"title":"Was ein KI-Agent ist","description":"","frontmatter":{"title":"Was ein KI-Agent ist"},"headers":[],"relativePath":"kapitel/01-was-ein-ki-agent-ist.md","filePath":"kapitel/01-was-ein-ki-agent-ist.md"}'),u={name:"kapitel/01-was-ein-ki-agent-ist.md"};function o(g,e,c,b,f,m){const n=t("FeedbackForm");return r(),s("div",null,[e[0]||(e[0]=a('<p><img src="'+d+'" alt="KI-Agent als Arbeitsassistenz"></p><h1 id="kapitel-1-was-ein-ki-agent-ist" tabindex="-1">Kapitel 1: Was ein KI-Agent ist <a class="header-anchor" href="#kapitel-1-was-ein-ki-agent-ist" aria-label="Permalink to &quot;Kapitel 1: Was ein KI-Agent ist&quot;">​</a></h1><h2 id="vom-chat-zur-delegation" tabindex="-1">Vom Chat zur Delegation <a class="header-anchor" href="#vom-chat-zur-delegation" aria-label="Permalink to &quot;Vom Chat zur Delegation&quot;">​</a></h2><p>Sie haben eine Frage. Sie öffnen ein Chatfenster, tippen sie ein und bekommen eine Antwort. Das ist ein Chatbot. Hilfreich, schnell, aber grundsätzlich reaktiv. Er antwortet auf das, was Sie schreiben. Er merkt sich nichts über die Sitzung hinaus, sofern Sie ihm keinen zusätzlichen Kontext geben. Er hat keinen Zugriff auf Ihre Dateien, Ihren Kalender oder Ihre Projekte. Und er führt keine Schritte durch, die Sie nicht ausdrücklich angestoßen haben.</p><p>Ein KI-Agent ist etwas anderes.</p><p>Ein Agent bekommt nicht nur eine Frage, sondern ein Ziel. Er kann Informationen aufnehmen, eine Aufgabe in Teilschritte zerlegen, Werkzeuge nutzen, Ergebnisse prüfen und den nächsten Schritt daraus ableiten. Im besten Fall arbeitet er wie eine gute Assistenzkraft: Sie geben Auftrag, Kontext, Grenzen und Qualitätsmaßstab vor. Der Agent erledigt die Vorarbeit. Sie prüfen und entscheiden.</p><p>Für dieses Buch reicht deshalb eine praktische Arbeitsdefinition:</p><blockquote><p>Ein KI-Agent ist ein KI-System, das ein Ziel verfolgt, dabei eigenständig Zwischenschritte plant, Werkzeuge nutzen kann und seine Arbeit an definierten Grenzen, Budgets und Freigaben ausrichtet.</p></blockquote><p>Diese Definition ist bewusst bodenständig. Sie hilft mehr als die große Frage, ob Agenten irgendwann vollständig autonom arbeiten. Für Selbständige zählt nicht Science-Fiction, sondern die Frage: Welche Aufgabe kann ein Agent heute zuverlässig vorbereiten, ohne dass Sie Kontrolle verlieren?</p><h2 id="der-unterschied-zwischen-chatbot-workflow-und-agent" tabindex="-1">Der Unterschied zwischen Chatbot, Workflow und Agent <a class="header-anchor" href="#der-unterschied-zwischen-chatbot-workflow-und-agent" aria-label="Permalink to &quot;Der Unterschied zwischen Chatbot, Workflow und Agent&quot;">​</a></h2><p>Um zu verstehen, was ein Agent ist, hilft es, ihn gegen zwei verwandte Konzepte abzugrenzen: den Chatbot auf der einen Seite und den festen Workflow auf der anderen.</p><p>Ein Chatbot beantwortet Fragen im Dialog. Seine Stärke liegt in Texterzeugung, Zusammenfassungen, Brainstorming und Erklärungen. Seine Grenze liegt darin, dass er keine Handlungen ausführt. Er denkt, aber er tut nicht.</p><p>Ein Workflow ist ein festgelegter Ablauf. Wenn Bedingung A erfüllt ist, folgt Schritt B, dann Schritt C. Workflows sind zuverlässig, weil sie immer gleich ablaufen. Sie sind schwach bei allem, was Abweichungen erfordert, weil jede neue Situation eine Anpassung des festgelegten Pfades verlangt. Ein klassisches Beispiel: Wenn eine neue Rechnung im Posteingang landet, extrahiere die Daten und trage sie in die Tabelle ein. Das funktioniert, solange Rechnungen immer gleich aussehen.</p><p>Ein Agent verbindet beides und geht darüber hinaus. Er bekommt ein Ziel, nicht einen festen Ablauf. Er entscheidet eigenständig, welche Schritte notwendig sind, welche Werkzeuge er nutzt, in welcher Reihenfolge er vorgeht und wann er ein Zwischenergebnis zur Prüfung vorlegt. Er kann mit unerwarteten Situationen umgehen, weil er nicht einem Script folgt, sondern das Ziel im Blick behält und seinen Weg dorthin dynamisch anpasst.</p><p>Diese Unterscheidung ist zentral für die gesamte Buchlogik. Viele Selbständige brauchen zu Beginn keinen Agenten, sondern einen besseren Workflow oder einen gut formulierten Prompt. Die Kunst liegt darin zu erkennen, wann welche Lösung passt.</p><p>Anthropic beschreibt diesen Unterschied ähnlich: Workflows folgen vordefinierten Pfaden, während Agenten dynamisch entscheiden, wie sie eine Aufgabe angehen. OpenAI beschreibt Agenten in der aktuellen Agents-Dokumentation über die Kombination aus Modell, Werkzeugen, Guardrails, Handoffs und Nachvollziehbarkeit. Beide Sichtweisen laufen auf denselben praktischen Punkt hinaus: Je mehr ein System selbst entscheidet, desto wichtiger werden Grenzen, Protokolle und menschliche Prüfung.</p><h2 id="wann-ein-einfacher-prompt-reicht" tabindex="-1">Wann ein einfacher Prompt reicht <a class="header-anchor" href="#wann-ein-einfacher-prompt-reicht" aria-label="Permalink to &quot;Wann ein einfacher Prompt reicht&quot;">​</a></h2><p>Ein guter Prompt ist die einfachste Lösung und meistens die richtige, solange die Aufgabe klar umrissen ist, einmalig oder selten vorkommt, keine externen Werkzeuge braucht und das Ergebnis direkt im Chatfenster entstehen kann.</p><p>Beispiele dafür sind das Umformulieren eines Absatzes, das Zusammenfassen einer Notiz, das Brainstormen von Ideen für einen Blogartikel oder das Erstellen einer einfachen Gliederung. Hier ist ein Prompt das richtige Mittel, weil er schnell, transparent und ausreichend ist.</p><p>Die Schwäche des Prompts zeigt sich, wenn die Aufgabe mehrere Schritte erfordert, wenn Daten aus verschiedenen Quellen zusammengeführt werden müssen oder wenn die Aufgabe regelmäßig wiederkehrt und jedes Mal neu angestoßen werden müsste. Dann lohnt sich der Blick auf strukturiertere Lösungen.</p><h2 id="wann-ein-workflow-die-bessere-wahl-ist" tabindex="-1">Wann ein Workflow die bessere Wahl ist <a class="header-anchor" href="#wann-ein-workflow-die-bessere-wahl-ist" aria-label="Permalink to &quot;Wann ein Workflow die bessere Wahl ist&quot;">​</a></h2><p>Ein fester Workflow lohnt sich, wenn eine Aufgabe oft vorkommt, immer die gleiche Struktur hat und das Ergebnis klar definiert ist. Klassische Beispiele für Selbständige sind das Umbenennen von Dateien nach einem einheitlichen Schema, das Zusammenführen von Tabellendaten aus verschiedenen Monaten, das Versenden einer wöchentlichen Statusübersicht an feste Empfänger oder das Erstellen eines Angebotsentwurfs auf Basis einer Vorlage.</p><p>Workflows sind zuverlässig. Sie sind vorhersehbar. Und sie sind leicht zu prüfen, weil das Ergebnis immer gleich aussehen soll. Für wiederkehrende, strukturierte Aufgaben ist ein gut aufgebauter Workflow einem Agenten häufig vorzuziehen, weil er einfacher, günstiger und leichter zu kontrollieren ist.</p><h2 id="wann-ein-agent-echten-mehrwert-bringt" tabindex="-1">Wann ein Agent echten Mehrwert bringt <a class="header-anchor" href="#wann-ein-agent-echten-mehrwert-bringt" aria-label="Permalink to &quot;Wann ein Agent echten Mehrwert bringt&quot;">​</a></h2><p>Ein Agent ist dann die richtige Wahl, wenn eine Aufgabe komplex ist und viele Zwischenschritte erfordert, wenn die Schritte von Ergebnissen abhängen, die erst während der Arbeit entstehen, wenn verschiedene Werkzeuge kombiniert werden müssen und wenn Sie nicht jeden Schritt selbst definieren können oder wollen.</p><p>Stellen Sie sich folgende Aufgabe vor: Sie wollen wissen, wie Ihre drei größten Wettbewerber ihr Angebot aktuell positionieren, was sie in den letzten Wochen kommuniziert haben und welche Themen noch unbesetzt sind. Um das herauszufinden, müsste jemand mehrere Websites prüfen, Texte vergleichen, Muster erkennen und die Erkenntnisse in einem klaren Briefing zusammenfassen. Das ist keine Frage, die ein einzelner Prompt beantwortet. Es ist eine Aufgabe, die mehrere Schritte erfordert, Werkzeuge wie eine Websuche, und das Urteilsvermögen, um Relevantes von Irrelevantem zu trennen.</p><p>Ein Agent kann diese Aufgabe übernehmen, eigenständig durch die notwendigen Schritte arbeiten, Zwischenergebnisse intern weiterverarbeiten und Ihnen am Ende ein Ergebnis vorlegen, das Sie prüfen, korrigieren und verwenden.</p><p>Wichtig dabei: Der Agent schließt die Aufgabe nicht ab. Sie tun es. Die menschliche Freigabe ist kein optionaler Schritt, sondern ein grundlegendes Prinzip. Besonders bei allem, was externe Kommunikation, finanzielle Konsequenzen oder rechtliche Bedeutung hat.</p><h2 id="was-einen-agenten-technisch-ausmacht" tabindex="-1">Was einen Agenten technisch ausmacht <a class="header-anchor" href="#was-einen-agenten-technisch-ausmacht" aria-label="Permalink to &quot;Was einen Agenten technisch ausmacht&quot;">​</a></h2><p>Hinter jedem Agent steckt ein Sprachmodell, das Texte versteht und erzeugt. Was einen Agenten vom einfachen Chatbot unterscheidet, ist die Verbindung dieses Modells mit Werkzeugen, mit Gedächtnis und mit der Fähigkeit zur Planung.</p><p>Werkzeuge sind externe Fähigkeiten, die ein Agent nutzen kann: eine Websuche, das Lesen einer Datei, das Schreiben in ein Dokument, das Ausführen eines Programms, die Verbindung zu einem Kalender oder einer Datenbank. Ein Agent ohne Werkzeuge ist wie ein kompetenter Mitarbeiter ohne Schreibtisch und ohne Computer. Er kann denken, aber nicht handeln.</p><p>Gedächtnis ist die Fähigkeit, Informationen über einzelne Sitzungen hinaus zu behalten. Manche Agenten haben ein kurzfristiges Gedächtnis nur für die aktuelle Sitzung. Andere speichern Informationen dauerhaft und können bei der nächsten Aufgabe auf frühere Erfahrungen zurückgreifen. Für Selbständige ist langfristiges Gedächtnis besonders wertvoll, weil es bedeutet, dass ein Agent Ihren Stil kennt, Ihre Kundenprojekte kennt und Ihre Arbeitsweise versteht.</p><p>Planung ist die Fähigkeit, ein Ziel in Teilschritte zu zerlegen und diese Schritte in einer sinnvollen Reihenfolge auszuführen. Ein planender Agent fragt nicht nach jedem Schritt, was als nächstes zu tun ist. Er entwickelt eine eigene Strategie und passt sie an, wenn Ergebnisse neue Informationen liefern.</p><p>In der Praxis kommen zwei weitere Bausteine dazu.</p><p>Erstens: Grenzen. Ein Agent braucht klare Rechte. Darf er nur lesen oder auch schreiben? Darf er Dateien ändern? Darf er E-Mails vorbereiten oder versenden? Darf er Geld ausgeben, Bestellungen auslösen oder Kundendaten verarbeiten? Je stärker ein Werkzeug in die echte Welt eingreift, desto enger müssen die Rechte sein.</p><p>Zweitens: Beobachtbarkeit. Sie müssen nachvollziehen können, was der Agent getan hat. Welche Quellen hat er genutzt? Welche Dateien hat er geändert? Welche Annahmen hat er getroffen? Welche Schritte wurden übersprungen? Ohne diese Spur ist ein Agent schwer prüfbar. Mit dieser Spur wird er zu einem Werkzeug, dessen Ergebnisse Sie bewerten und verbessern können.</p><h2 id="die-funf-bauteile-eines-brauchbaren-agenten" tabindex="-1">Die fünf Bauteile eines brauchbaren Agenten <a class="header-anchor" href="#die-funf-bauteile-eines-brauchbaren-agenten" aria-label="Permalink to &quot;Die fünf Bauteile eines brauchbaren Agenten&quot;">​</a></h2><p>Ein Agenten-Setup für Selbständige sollte aus fünf Bauteilen bestehen.</p><table tabindex="0"><thead><tr><th>Bauteil</th><th>Was es leistet</th><th>Gute Einstiegsfrage</th></tr></thead><tbody><tr><td>Ziel</td><td>Beschreibt, was am Ende vorliegen soll</td><td>Woran erkennen Sie, dass die Aufgabe fertig ist?</td></tr><tr><td>Kontext</td><td>Liefert Dateien, Beispiele, Stil, Kundenwissen</td><td>Welche Informationen darf der Agent nutzen?</td></tr><tr><td>Werkzeuge</td><td>Erlauben Recherche, Dateiarbeit oder Automatisierung</td><td>Welche Zugriffe sind wirklich nötig?</td></tr><tr><td>Grenzen</td><td>Regeln Rechte, Budget, Stopps und Freigaben</td><td>Was darf der Agent ausdrücklich nicht tun?</td></tr><tr><td>Prüfspur</td><td>Macht Quellen, Schritte und Änderungen sichtbar</td><td>Wie prüfen Sie das Ergebnis in zwei Minuten?</td></tr></tbody></table><p>Fehlt eines dieser Bauteile, wird ein Agent schnell unzuverlässig. Ohne Ziel arbeitet er schwammig. Ohne Kontext rät er. Ohne Werkzeuge bleibt er ein Chatbot. Ohne Grenzen wird er riskant. Ohne Prüfspur müssen Sie ihm glauben, statt seine Arbeit kontrollieren zu können.</p><h2 id="autonomie-ist-kein-schalter" tabindex="-1">Autonomie ist kein Schalter <a class="header-anchor" href="#autonomie-ist-kein-schalter" aria-label="Permalink to &quot;Autonomie ist kein Schalter&quot;">​</a></h2><p>Viele Diskussionen über Agenten klingen so, als gäbe es nur zwei Zustände: manuell oder autonom. Das ist für die Praxis zu grob. Autonomie ist eine Leiter. Auf der ersten Stufe steht ein Prompt. Auf der zweiten Stufe ein Workflow. Auf der dritten Stufe ein Agent mit Werkzeugen. Auf der vierten Stufe arbeiten mehrere Agenten mit unterschiedlichen Rollen zusammen.</p><p><img src="'+l+'" alt="Entscheidungsleiter für Agentenarbeit"></p><p>Diese Leiter ist keine Rangliste. Ein Prompt ist nicht schlechter als ein Agent. Er ist nur einfacher. Und einfache Lösungen sind oft besser, weil sie leichter zu prüfen, günstiger und robuster sind.</p><p>Ein guter Einstieg lautet deshalb nicht: &quot;Wie mache ich diese Aufgabe möglichst agentisch?&quot; Die bessere Frage lautet: &quot;Was ist die einfachste Lösung, die zuverlässig genug ist?&quot; Erst wenn ein Prompt zu kurz greift und ein Workflow zu starr ist, lohnt sich ein Agent.</p><h2 id="das-prinzip-der-minimalen-komplexitat" tabindex="-1">Das Prinzip der minimalen Komplexität <a class="header-anchor" href="#das-prinzip-der-minimalen-komplexitat" aria-label="Permalink to &quot;Das Prinzip der minimalen Komplexität&quot;">​</a></h2><p>Eine der wichtigsten Empfehlungen für den Einstieg in die Agentenarbeit lautet: Beginnen Sie immer mit der einfachsten Lösung. Ein guter Prompt ist besser als ein schlecht konfigurierter Workflow. Ein verlässlicher Workflow ist besser als ein schlecht definierter Agent. Mehr Autonomie bedeutet nicht automatisch bessere Ergebnisse. Sie bedeutet mehr Spielraum für Fehler, wenn Ziele, Grenzen und Prüfmechanismen nicht klar sind.</p><p>Agenten sollten nicht eingesetzt werden, weil sie modern klingen. Sie sollten eingesetzt werden, weil eine konkrete Aufgabe von ihren Eigenschaften profitiert: von der Fähigkeit, eigenständig zu planen, Werkzeuge zu kombinieren und in einem iterativen Prozess bessere Ergebnisse zu liefern, als ein einfacher Schritt es könnte.</p><p>Dieses Prinzip zieht sich durch das gesamte Buch. Jedes Kapitel fragt zuerst: Was ist die einfachste Lösung, die zuverlässig funktioniert? Und dann: Wann lohnt es sich, einen Schritt weiterzugehen?</p><p>Ein nützlicher Test besteht aus drei Fragen:</p><ol><li>Muss die Aufgabe während der Bearbeitung Entscheidungen treffen, die Sie vorher nicht vollständig auflisten können?</li><li>Muss die Aufgabe mehrere Werkzeuge oder Quellen kombinieren?</li><li>Ist das Ergebnis wertvoll genug, dass sich Einrichtung, Kontrolle und Nachbesserung lohnen?</li></ol><p>Wenn Sie nur eine dieser Fragen mit Ja beantworten, reicht meistens ein Prompt oder Workflow. Wenn Sie zwei oder drei Fragen mit Ja beantworten, kann ein Agent sinnvoll sein. Wenn zusätzlich externe Kommunikation, Kundendaten, Zahlungen oder rechtlich relevante Inhalte betroffen sind, gehört eine Freigabestufe zwingend dazu.</p><h2 id="die-vier-grundeigenschaften-eines-guten-agenten-setups" tabindex="-1">Die vier Grundeigenschaften eines guten Agenten-Setups <a class="header-anchor" href="#die-vier-grundeigenschaften-eines-guten-agenten-setups" aria-label="Permalink to &quot;Die vier Grundeigenschaften eines guten Agenten-Setups&quot;">​</a></h2><p>Wer mit Agenten arbeitet, sollte von Anfang an vier Eigenschaften im Blick behalten, die über Erfolg oder Misserfolg entscheiden.</p><p>Erstens: Ein klares Ziel. Agenten sind keine allwissenden Assistenten. Sie brauchen eine präzise Aufgabe, ein definiertes Ausgabeformat und klare Grenzen dessen, was sie tun dürfen und was nicht.</p><p>Zweitens: Ein Budget. Zeit, Tokens und API-Kosten sind begrenzte Ressourcen. Jede Agentenroutine sollte ein definiertes Maximum haben, bei dessen Erreichen sie anhält und Rückfrage stellt, anstatt weiter zu laufen.</p><p>Drittens: Stopregeln. Ein Agent sollte wissen, wann er aufhören soll. Nicht nur wenn er fertig ist, sondern auch wenn er feststeckt, wenn er unsichere Entscheidungen treffen müsste oder wenn das Ergebnis von einer menschlichen Einschätzung abhängt.</p><p>Viertens: Menschliche Freigabe an den richtigen Stellen. Nicht für jeden Schritt. Aber für alle Schritte, die irreversibel sind, externe Konsequenzen haben oder Unsicherheiten enthalten, die ein Mensch besser beurteilt als ein Modell.</p><p>Diese vier Eigenschaften sind kein bürokratisches Gerüst. Sie sind die Grundlage dafür, dass Agenten tatsächlich verlässlich funktionieren, anstatt gelegentlich gut und gelegentlich problematisch.</p><p>Das NIST AI Risk Management Framework ist für größere Organisationen geschrieben, aber die Grundlogik passt auch für Selbständige: Risiken sollen nicht erst betrachtet werden, wenn etwas schiefgelaufen ist, sondern als Teil von Planung, Messung und Betrieb. Übersetzt auf Ihren Alltag bedeutet das: Definieren Sie vorher, was der Agent darf, welche Fehler besonders teuer wären, wie Sie Ergebnisse prüfen und wann eine Aufgabe gestoppt wird.</p><h2 id="agenten-als-mitarbeiter-denken" tabindex="-1">Agenten als Mitarbeiter denken <a class="header-anchor" href="#agenten-als-mitarbeiter-denken" aria-label="Permalink to &quot;Agenten als Mitarbeiter denken&quot;">​</a></h2><p>Eine Metapher, die sich durch das gesamte Buch zieht: Denken Sie an einen Agenten wie an einen neuen Mitarbeiter. Nicht wie an einen Computer, der Befehle ausführt. Sondern wie an eine Person, die Sie briefen, die Fragen stellt, wenn etwas unklar ist, die Ergebnisse liefert, die Sie prüfen, und die mit der Zeit besser wird, weil sie mehr über Ihre Arbeitsweise und Ihre Projekte weiß.</p><p>Einem neuen Mitarbeiter gibt man am Anfang keine kritischen Aufgaben mit großer Wirkung. Man gibt ihm überschaubare Aufgaben, schaut sich die Ergebnisse an, gibt Feedback und erweitert seinen Verantwortungsbereich schrittweise, wenn das Vertrauen gewachsen ist.</p><p>Genauso sollte man mit Agenten umgehen. Das erste Projekt ist nicht die automatische Kundenkommunikation. Das erste Projekt ist ein Recherchebriefing, das Sie danach kontrollieren. Dann ein Entwurf, den Sie überarbeiten. Dann eine Routineaufgabe, die Sie eine Woche lang täglich prüfen. Und dann, wenn Sie wissen, wie der Agent arbeitet und wo seine Grenzen liegen, können Sie ihm mehr Verantwortung geben.</p><p>Für Selbständige ist diese Mitarbeiter-Metapher besonders nützlich, weil sie Verantwortung sichtbar macht. Ein neuer Mitarbeiter darf vielleicht eine Angebotsstruktur vorbereiten, aber nicht eigenständig Rabattgrenzen ändern. Er darf eine Antwort an einen schwierigen Kunden entwerfen, aber nicht ohne Freigabe absenden. Er darf Belege sortieren, aber nicht eigenständig steuerliche Entscheidungen treffen. Genau so sollten Agentenrechte wachsen: klein starten, Ergebnis prüfen, Muster erkennen, Rechte erweitern.</p><h2 id="ein-beispiel-aus-dem-arbeitsalltag" tabindex="-1">Ein Beispiel aus dem Arbeitsalltag <a class="header-anchor" href="#ein-beispiel-aus-dem-arbeitsalltag" aria-label="Permalink to &quot;Ein Beispiel aus dem Arbeitsalltag&quot;">​</a></h2><p>Nehmen wir eine typische Situation: Sie wollen aus drei Kundengesprächen ein neues Angebotspaket entwickeln.</p><p>Ein Chatbot kann Ihnen helfen, die Notizen zusammenzufassen oder Formulierungen zu verbessern. Ein Workflow kann die Mitschriften immer gleich benennen, ablegen und in ein Standardformular übertragen. Ein Agent kann mehr: Er liest die drei Mitschriften, erkennt wiederkehrende Probleme, vergleicht sie mit Ihrer bestehenden Leistungsbeschreibung, schlägt drei Paketvarianten vor, markiert offene Annahmen und erstellt eine Liste der Fragen, die Sie vor Veröffentlichung noch klären müssen.</p><p>Das Ergebnis ist nicht automatisch marktreif. Aber es ist eine deutlich bessere Vorarbeit als ein leerer Bildschirm. Ihre Aufgabe verschiebt sich: Sie sammeln nicht mehr alle Einzelteile selbst, sondern beurteilen, ob die Vorarbeit stimmt.</p><p>Genau darin liegt der wirtschaftliche Nutzen. Agenten ersetzen nicht Ihre Urteilskraft. Sie verlagern Ihre Arbeit von Suche, Sortierung und Rohentwurf hin zu Entscheidung, Korrektur und Freigabe.</p><h2 id="drei-aufgaben-zum-einstieg" tabindex="-1">Drei Aufgaben zum Einstieg <a class="header-anchor" href="#drei-aufgaben-zum-einstieg" aria-label="Permalink to &quot;Drei Aufgaben zum Einstieg&quot;">​</a></h2><p>Die drei Fragen lauten:</p><ol><li>Welche wiederkehrende Aufgabe kostet Sie jede Woche am meisten Zeit, obwohl sie klar strukturiert ist?</li><li>Welche Recherche oder Zusammenfassung wünschen Sie sich, die Sie bisher nicht regelmäßig machen, weil sie zu zeitaufwändig ist?</li><li>Welche Routine in Ihrer Arbeit wäre sofort besser, wenn jemand anderes die Vorarbeit erledigt?</li></ol><p>Die Antworten auf diese drei Fragen sind Ihre persönliche Landkarte für dieses Buch. Sie zeigen Ihnen, wo Sie anfangen sollten, was sich lohnt und worauf Sie sich im nächsten Kapitel am stärksten konzentrieren können.</p><p>Im nächsten Kapitel lernen Sie die vier konkreten Werkzeuge kennen, die in diesem Buch im Mittelpunkt stehen: Clawbot, Hermes, Claude Code und Codex. Sie werden verstehen, was jedes dieser Werkzeuge kann, wofür es besonders geeignet ist, was seine Schwächen sind und wie Sie entscheiden, welches für Ihre Aufgaben passt.</p><h2 id="quellen-und-weiterfuhrende-links" tabindex="-1">Quellen und weiterführende Links <a class="header-anchor" href="#quellen-und-weiterfuhrende-links" aria-label="Permalink to &quot;Quellen und weiterführende Links&quot;">​</a></h2><ul><li>Anthropic: &quot;Building effective agents&quot;, 19. Dezember 2024. <a href="https://www.anthropic.com/engineering/building-effective-agents" target="_blank" rel="noreferrer">https://www.anthropic.com/engineering/building-effective-agents</a></li><li>OpenAI: Agents SDK und Agents-Dokumentation. <a href="https://platform.openai.com/docs/guides/agents-sdk" target="_blank" rel="noreferrer">https://platform.openai.com/docs/guides/agents-sdk</a> und <a href="https://platform.openai.com/docs/guides/agents" target="_blank" rel="noreferrer">https://platform.openai.com/docs/guides/agents</a></li><li>OpenAI Agents SDK: technische Referenz zu Agents, Tools, Guardrails und Handoffs. <a href="https://openai.github.io/openai-agents-python/agents/" target="_blank" rel="noreferrer">https://openai.github.io/openai-agents-python/agents/</a></li><li>NIST: Artificial Intelligence Risk Management Framework. <a href="https://www.nist.gov/itl/ai-risk-management-framework" target="_blank" rel="noreferrer">https://www.nist.gov/itl/ai-risk-management-framework</a></li></ul>',77)),h(n)])}const w=i(u,[["render",o]]);export{k as __pageData,w as default};
